<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<div class="wrap mlp-admin"><h1><?php esc_html_e( 'Attendance', 'madrasa-lms-pro' ); ?></h1><form class="card p-3 mb-3 mlp-attendance-form"><div class="row g-2"><div class="col"><select class="form-control" name="student_id"><?php foreach ( $students as $student ) : ?><option value="<?php echo esc_attr( $student['id'] ); ?>"><?php echo esc_html( $student['name'] ); ?></option><?php endforeach; ?></select></div><div class="col"><input type="date" class="form-control" name="attendance_date" value="<?php echo esc_attr( gmdate( 'Y-m-d' ) ); ?>"></div><div class="col"><select class="form-control" name="status"><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option></select></div><div class="col"><button class="button button-primary"><?php esc_html_e( 'Save Attendance', 'madrasa-lms-pro' ); ?></button></div></div></form><button class="button" onclick="window.print()"><?php esc_html_e( 'Printable Sheet', 'madrasa-lms-pro' ); ?></button><table class="widefat striped"><thead><tr><th><?php esc_html_e( 'Student', 'madrasa-lms-pro' ); ?></th><th><?php esc_html_e( 'Date', 'madrasa-lms-pro' ); ?></th><th><?php esc_html_e( 'Status', 'madrasa-lms-pro' ); ?></th></tr></thead><tbody><?php foreach ( $rows as $row ) : ?><tr><td><?php echo esc_html( $row['student_id'] ); ?></td><td><?php echo esc_html( $row['attendance_date'] ); ?></td><td><?php echo esc_html( $row['status'] ); ?></td></tr><?php endforeach; ?></tbody></table></div>
